import { beforeEach, describe, expect, test } from "bun:test"
import { Schema } from "effect"

const src = await Bun.file(new URL("../public/oc-theme-preload.js", import.meta.url)).text()

const run = () => Function(src)()

// The brand seed is generated by script/panacode-brand-apply.ts, so the expected paper and ink follow the active pack.
const Seed = Schema.Struct({ darkPaper: Schema.String, lightPaper: Schema.String, dark: Schema.String, light: Schema.String })

const seed = Schema.decodeUnknownSync(Schema.fromJsonString(Seed))(/var brandSeed = (\{.*\})/.exec(src)![1])

const ink = (css: string) => /--text-strong:([^;]+);/.exec(css)![1]

const light = { background: seed.lightPaper, ink: ink(seed.light) }

const dark = { background: seed.darkPaper, ink: ink(seed.dark) }

const setSystemDark = (matches: boolean) =>
  Object.defineProperty(window, "matchMedia", {
    value: () => ({ matches }),
    configurable: true,
  })

beforeEach(() => {
  document.head.innerHTML = ""
  document.documentElement.removeAttribute("data-theme")
  document.documentElement.removeAttribute("data-color-scheme")
  document.documentElement.removeAttribute("data-default-color-scheme")
  document.documentElement.removeAttribute("data-brand")
  document.documentElement.style.removeProperty("background-color")
  document.documentElement.style.removeProperty("color-scheme")
  Object.defineProperty(window, "electron", { configurable: true, value: undefined })
  localStorage.clear()
  setSystemDark(false)
})

describe("theme preload", () => {
  test.each([
    { stored: undefined, systemDark: false, scheme: "dark", ...dark },
    { stored: "dark", systemDark: false, scheme: "dark", ...dark },
    { stored: "light", systemDark: true, scheme: "light", ...light },
    { stored: "system", systemDark: true, scheme: "dark", ...dark },
  ])(
    "paints the default theme in $scheme for stored scheme $stored (system dark: $systemDark)",
    ({ stored, systemDark, scheme, background, ink }) => {
      setSystemDark(systemDark)

      if (stored) localStorage.setItem("opencode-color-scheme", stored)
      run()

      expect(document.documentElement.dataset.theme).toBe("panacode")
      expect(document.documentElement.dataset.brand).toBe("panacode")
      expect(document.documentElement.dataset.colorScheme).toBe(scheme)
      expect(document.documentElement.style.backgroundColor).toBe(background)
      expect(document.getElementById("oc-theme-preload-seed")?.textContent).toContain(`--text-strong:${ink}`)
    },
  )

  test.each([false, true])("desktop first paint follows the system dark preference %s", (systemDark) => {
    document.documentElement.dataset.defaultColorScheme = "system"
    setSystemDark(systemDark)
    run()
    expect(document.documentElement.dataset.colorScheme).toBe(systemDark ? "dark" : "light")
    expect(document.documentElement.style.backgroundColor).toBe(systemDark ? dark.background : light.background)
  })

  test.each([false, true])("native window tone seeds the first renderer frame even with a different media query (%s)", (nativeDark) => {
    const mode = nativeDark ? "dark" : "light"
    document.documentElement.dataset.defaultColorScheme = "system"
    Object.defineProperty(window, "electron", { configurable: true, value: { bootstrap: { systemMode: mode } } })
    setSystemDark(!nativeDark)
    run()
    expect(document.documentElement.dataset.colorScheme).toBe(mode)
    const paper = nativeDark ? dark.background : light.background
    expect(document.documentElement.style.backgroundColor).toBe(paper)
    expect(document.getElementById("oc-theme-preload-seed")?.textContent).toContain(`--background-base:${paper};`)
    localStorage.setItem("opencode-color-scheme", nativeDark ? "light" : "dark")
    run()
    expect(document.documentElement.dataset.colorScheme).toBe(nativeDark ? "light" : "dark")
  })

  test.each([
    { scheme: "light", key: "opencode-theme-css-light", css: "--background-base:#fff;", expected: "light" },
    { scheme: "dark", key: "opencode-theme-css-dark", css: "--background-base:#010203;", expected: "dark" },
  ])("restores the cached $expected css of a custom theme", ({ scheme, key, css, expected }) => {
    localStorage.setItem("opencode-theme-id", "nightowl")

    if (scheme) localStorage.setItem("opencode-color-scheme", scheme)
    localStorage.setItem(key, css)
    run()

    expect(document.documentElement.dataset.theme).toBe("nightowl")
    expect(document.documentElement.dataset.colorScheme).toBe(expected)
    expect(document.getElementById("oc-theme-preload")?.textContent).toContain(css)
  })
})
